/**
 * @file init.h
 * @brief Public interface and data structures for the lexical analyzer.
 * 
 * Defines lexical tokens, enumeration types, primary structures
 * Also exposes the nextToken() function prototype for the syntax analyzer
 * 
 * @author Tadeáš Vykopal (xvykopt00)
 * @date 2026
 */

#ifndef LEX_INIT_H
#define LEX_INIT_H

/**
* @brief Types of lexical tokens generated by the lexer.
*/
typedef enum {
    // Structural
    TOKEN_EOF,               /**< End of file marker */
    TOKEN_EOL,               /**< End of line marker */
    TOKEN_ANNOTATION_MAIN,   /**< The '\@main' annotation (treated as a single token) */
    TOKEN_INDENT,            /**< Increase in indentation level */
    TOKEN_DEDENT,            /**< Decrease in indentation level */

    // Keywords
    TOKEN_KW_DEF,            /**< Keyword: def */
    TOKEN_KW_DO,             /**< Keyword: do */
    TOKEN_KW_ELSE,           /**< Keyword: else */
    TOKEN_KW_IF,             /**< Keyword: if */
    TOKEN_KW_IMPORT,         /**< Keyword: import */
    TOKEN_KW_RETURN,         /**< Keyword: return */
    TOKEN_KW_THEN,           /**< Keyword: then */
    TOKEN_KW_VAL,            /**< Keyword: val */
    TOKEN_KW_VAR,            /**< Keyword: var */
    TOKEN_KW_WHILE,          /**< Keyword: while */
    
    // Identifiers and literals
    TOKEN_ID,                /**< Variable or function identifier */
    TOKEN_INT_LITERAL,       /**< Integer numeric literal */
    TOKEN_DOUBLE_LITERAL,    /**< Floating-point numeric literal */
    TOKEN_STRING_LITERAL,    /**< Text string literal (standard or block) */

    // Types
    TOKEN_TYPE_INT,          /**< Built-in type: Int */
    TOKEN_TYPE_DOUBLE,       /**< Built-in type: Double */
    TOKEN_TYPE_STRING,       /**< Built-in type: String */
    TOKEN_TYPE_UNIT,         /**< Built-in type: Unit */

    // Operators
    TOKEN_ASSIGN,            /**< Assignment operator: = */
    TOKEN_PLUS,              /**< Addition operator: + */
    TOKEN_MINUS,             /**< Subtraction operator: - */
    TOKEN_MUL,               /**< Multiplication operator: * */
    TOKEN_DIV,               /**< Division operator: / */
    TOKEN_EQ,                /**< Equality operator: == */
    TOKEN_NEQ,               /**< Inequality operator: != */
    TOKEN_LT,                /**< Less than operator: < */
    TOKEN_LTE,               /**< Less than or equal operator: <= */
    TOKEN_GT,                /**< Greater than operator: > */
    TOKEN_GTE,               /**< Greater than or equal operator: >= */

    // Separators
    TOKEN_LPAREN,            /**< Left parenthesis: ( */
    TOKEN_RPAREN,            /**< Right parenthesis: ) */
    TOKEN_COLON,             /**< Colon separator: : */
    TOKEN_COMMA,             /**< Comma separator: , */
    TOKEN_DOT,               /**< Dot/period separator: . */
    TOKEN_SEMICOLON,         /**< Semicolon separator: ; */
} TokenType;

/**
 * @brief Internal states of the lexer's finite state machine.
 */
typedef enum {
    START,           /**< Initial state, expects the beginning of a new lexeme */
    LINE_START,      /**< Evaluates leading whitespace for indentation logic */

    IDENTIFIER,      /**< Reading an identifier or keyword */

    INT,             /**< Reading an integer literal */
    DOUBLE,          /**< Reading the fractional part of a double literal */
    DOUBLE_EXP,      /**< Reading the exponent part of a double literal */
    
    STRING,          /**< Reading a standard string literal */
    STRING_ESC,      /**< Reading an escape sequence inside a string */
    BLOCK_STRING,    /**< Reading a multiline block string literal */

    MORE,            /**< Lookahead state for '>' or '>=' */
    LESS,            /**< Lookahead state for '<' or '<=' */
    SLASH,           /**< Lookahead state for division or comments */

    LINE_COMMENT,    /**< Ignoring characters until the end of the line */
    BLOCK_COMMENT,   /**< Ignoring characters until the block comment is closed */

} LexerState;

/**
* @brief Struct of the dynamically allocated text buffer for loading lexems
*/
typedef struct {
    char *text;
    int length;
    int capacity;
} StringBuffer;

/** 
* @brief Struct of the token passed to the syntax analyzer
*/
typedef struct TOKEN
{
    TokenType type;
    union { //found out the previously suggested void pointer method is about a bazoogalion times slower and harder to code than this due to constant mallocs, frees and shit like that
        int intValue;
        double doubleValue;
        char *stringValue;
    } val;

    int lineNumber;
    //int col_number; //we could have prettier error msgs with this but it would slow us down, pointless...
} Token;

/**
* @brief Obtains the next token from stdin using a finite state machine
*
* Uses a buffer to hold context and a line for emiting dedent tokens.
*
* @return The struct Token obtaining the token type and in some cases it's value in a union
*/
Token nextToken();

#endif //INIT_H
